# Case content is maintained as paired Chinese / English text.
# Statements are grounded in the source index in docs/sources.md.
CASES = {
'qingju': {
 'title':['青桔：让成长体系，回到骑行本身。','Qingju: making growth part of the ride.'],
 'deck':['将“提高活跃度”的业务目标，转化为围绕休闲骑行的探索、记录与奖励体验。','Turning an engagement brief into an experience built around discovery, memories and rewards in leisure cycling.'],
 'brief':[['青桔想用成长体系提高活跃度，但任务、等级、勋章、积分各管各的，用户要点进很深才知道自己的进展。', 'Qingju wanted its growth system to raise engagement, but tasks, levels, badges and points sat apart, and riders had to dig deep to see their own progress.'], ['我提出从休闲骑行切入，让奖励跟着“找路线、骑行、记录”走，而不是另开一套任务。我参与了调研访谈，做了问题拆解、画像、旅程图、用户流程和低保真，我们在这之上完成了高保真方案。', 'I proposed starting from leisure riding, so that rewards follow finding a route, riding it and recording it, instead of a separate task list. I contributed to the research and interviews, and made the problem framing, personas, journey map, user flow and low-fidelity wireframes; as a team we built the high-fidelity proposal on top of them.'], ['我们四人团队的方案获知群中国产品设计大赛青桔赛段最佳方案奖。', 'Our four-person team’s proposal won the Best Proposal Award in the Qingju growth-system track of the Zhiqun China Design Award & Competition.']],
 'facts':[['项目背景','Context','青桔（滴滴）商业委托 · 训练营结项','Commercial brief from Qingju (DiDi) · Programme capstone'],['我的职责','My role','提出休闲骑行方向；参与调研与访谈；问题拆解、画像、旅程图、用户流程、低保真','Proposed the leisure-cycling direction; contributed to research and interviews; problem framing, personas, journeys, user flow, wireframes'],['项目时间','Period','2021 · 2 个月 · 4 人团队','2021 · 2 months · team of four'],['协作成果','Team output','研究、概念方案与高保真 · 知群中国产品设计大赛（青桔单车用户成长体系赛段）最佳方案奖','Research, concept & high fidelity · Best Proposal Award, Zhiqun China Design Award & Competition (Qingju growth-system track)']],
 'image':'qingju-cover','source':'https://www.figma.com/design/lfqzkEzhH33yq5kvIkNEqW?node-id=2206-19887',
 'sections':[
 {'label':['01 / 问题','01 / The challenge'],'title':['为什么用户需要这套成长体系？','Why would a rider care about a growth system?'],'text':[
 ['原始任务是改良青桔的成长体系，以提高用户活跃度。我梳理了当时的产品，发现任务、等级、勋章与积分相互分散；用户需要进入较深层级，才能理解自己的进展与权益。','The brief was to improve Qingju’s growth system with user engagement as the goal. My review of the product at the time found tasks, levels, badges and points separated from one another, with progress and benefits buried in the navigation.'],
 ['动手之前，我先把“活跃”拆开：一个用户从试用、体验、形成习惯到愿意推荐，每个阶段看什么指标、过了哪条线才算数。当时的判断是，通勤的需求相对固定，能多出来的骑行在休闲时间里。','Before designing anything, I broke “active” down: from trial to first rides, habit and advocacy, what to measure at each stage and which threshold counts. The judgement at the time was that commuting demand is relatively fixed, so the extra rides would have to come from leisure time.'],
 ['我提出把休闲骑行作为研究方向：通勤通常有固定目的，而在公园、绿道和城市探索中，人们还有“去哪里、看什么、如何留下回忆”的问题。这是我们选择探索的场景假设，随后围绕它开展研究。','I proposed leisure cycling as the research direction. Commuting usually has a fixed destination; parks, greenways and city exploration introduce questions about where to go, what to see and what to remember. This was a scenario hypothesis that shaped the research.']],
 'insight':['成长不应只是开锁之后累积的数字。它需要和用户想完成的骑行体验发生联系。','Growth should connect to what people want from a ride, rather than remain a number that accumulates after unlocking a bike.']},
 {'label':['02 / 研究','02 / Research'],'title':['先理解骑行，再讨论奖励。','Understand the ride before designing the reward.'],'text':[
 ['我们结合访谈、问卷与实地观察，关注休闲骑行者的行为、动机、分享方式，以及对成长权益的感知。我们访谈了 11 个人，回收 128 份问卷，其中 85 份有效。','We combined interviews, a questionnaire and field observation to explore leisure riders’ behaviour, motivations, sharing habits and awareness of benefits. We interviewed 11 people and collected 128 questionnaire returns, 85 of them valid.'],
 ['访谈摘要中反复出现的线索包括：寻找不熟悉的小风景，与朋友一起探店，以及记录、回顾和分享骑行经历。问卷里约九成的人没有注意过成长体系。我参与前期调研与访谈，并将这些线索整理到画像与旅程中。','Recurring themes in the interview summaries included discovering unfamiliar places, visiting shops with friends, and recording or sharing a ride. In the questionnaire, about nine in ten had not noticed the growth system. I contributed to the early research and interviews, then translated these themes into personas and journeys.']],
 'image':'qingju-research','caption':['原始研究摘要，聚焦休闲骑行场景。','Original research summary, focused on leisure riding.']},
 {'label':['03 / 综合','03 / Synthesis'],'title':['把机会放回骑行前、中、后。','Map the opportunities before, during and after a ride.'],'text':[
 ['单独列出“探索、社交、记录”并不足以指导界面。我通过用户建模与旅程图，把这些需求放回具体时刻：选择路线、在途中停留、结束后整理经历。','A list of needs—exploration, social connection, memories—was not enough to guide the interface. Through user modelling and journey maps, I connected them to specific moments: choosing a route, pausing along the way and reflecting afterwards.']],
 'steps':[
 [['骑行前','Before'],['降低路线选择成本','Make choosing easier'],['帮助用户找到符合兴趣的地点与路线，减少在不熟悉区域反复查找的负担。','Help people find places and routes that match their interests, reducing the effort of planning in an unfamiliar area.']],
 [['骑行中','During'],['保留探索与停留的空间','Leave room to explore'],['围绕沿途地点与骑行进程建立体验，避免成长体系与实际行为脱节。','Connect the experience to places along the route and progress through the ride.']],
 [['骑行后','After'],['让经历值得回顾','Make the ride memorable'],['把记录、奖励和分享连接起来，为一次骑行留下可以继续使用的内容。','Connect memories, rewards and sharing so the experience has value beyond the journey itself.']]],
 'image':'qingju-journey','caption':['项目原始旅程图：综合行为与机会点。','Original journey map: a synthesis of behaviours and opportunities.']},
 {'label':['04 / 设计决策','04 / Design decision'],'title':['让奖励跟随体验，而不是另开一套任务。','Let rewards follow the experience.'],'text':[
 ['从画像到方案，中间有一步筛选。我给三类用户各写一句观点陈述，再改写成“我们如何”问题；头脑风暴出的想法按新颖度、实用性、可行性、相关度四个维度评估，留下五个方向：宝藏地图、宝箱系统、路线讨论圈、骑行回忆、简化记录。最后把它们放进“入口 → 成长形式 → 出口”，拼成一套体系。','Between personas and proposal there was a filtering step. I wrote a point-of-view statement for each of the three rider types and turned each into a “how might we” question. Ideas from brainstorming were assessed on novelty, usefulness, feasibility and relevance, leaving five directions: a treasure map, treasure chests, route discussions, ride memories and simpler recording. Finally we placed them into entry, mechanism and outcome so that they formed one system.'],
 ['我们没有把“增加一套积分与勋章”作为唯一答案，而是从路线探索出发，把骑行记录和成长权益接到同一条路径上。用户先获得骑行本身的价值，再理解参与如何带来奖励。','We did not treat another points-and-badges system as the only answer. Instead, we connected route discovery, ride records and growth benefits in one path. The ride itself provides value first; rewards make sense within that experience.'],
 ['画低保真之前，我先把整条路径画成一张流程图，确认奖励、宝库和骑行回忆各自接在骑行结束后的哪一步。我负责的低保真阶段把机会转化为可讨论的页面与流程，包括路线选择、骑行记录、奖励和分享。这让团队能围绕入口与任务顺序进行讨论，再进入最终视觉方案。','Before wireframing, I drew the whole path as a flow chart to settle where rewards, the vault and ride memories attach once a ride ends. My low-fidelity work translated the opportunities into screens and flows for route selection, ride records, rewards and sharing. It gave the team a concrete basis for discussing entry points and task order before the final visual design.']],
 'image':'qingju-wireframes','caption':['原始低保真流程。个人贡献聚焦研究、用户建模、旅程与低保真；最终高保真为团队成果。点击可放大。','Original wireframe flow. My contribution focused on research, modelling, journeys and low fidelity; final high fidelity was a team output. Select to enlarge.']},
 {'label':['05 / 取舍','05 / Trade-offs'],'title':['探索可以很丰富，产品需要有边界。','A rich concept still needs boundaries.'],'text':[
 ['把路线、商铺与奖励连接起来，能够形成更完整的体验，也会增加内容、合作与运营成本。我们没有把每一个有趣的想法都加入首版，而是围绕骑行前后的核心路径组织方案。','Connecting routes, shops and rewards creates a more complete experience, but also brings content, partnership and operational costs. We did not include every interesting idea in the first proposal; we organised it around the core journey before and after riding.'],
 ['回看这个项目，我会先验证一个较小的闭环：用户能否找到想骑的路线、完成骑行，并理解记录与奖励的关系。更广泛的合作与生态设想，需要在这条路径成立之后再展开。','Looking back, I would validate a smaller loop first: can someone find a route they want to ride, complete it, and understand the relationship between the ride record and its reward? Wider partnerships should follow evidence that this loop works.']]},
 {'label':['06 / 交付与反思','06 / Outcome & reflection'],'title':['从业务目标，走到可讨论的完整方案。','From a business goal to a concrete experience proposal.'],'text':[
 ['这次项目形成了研究摘要、画像与旅程、低保真流程，以及团队高保真方案。我最核心的贡献，是提出休闲骑行方向，并将研究线索推进到具体流程。','The project produced a research synthesis, personas and journeys, wireframe flows, and a team high-fidelity proposal. My central contribution was proposing the leisure-cycling direction and carrying research themes into concrete flows.'],
 ['方案在知群中国产品设计大赛的青桔单车用户成长体系赛段获最佳方案奖，是四人团队的共同成果。','The proposal received the Best Proposal Award in the Qingju growth-system track of the Zhiqun China Design Award & Competition, as the joint work of a four-person team.'],
 ['下一步，我会观察真实骑行者能否独立理解并完成这条体验路径。','As a next step, I would observe whether riders can independently understand and complete the proposed journey.']], 'outcome':True},
 {'label':['07 / 2026 复盘','07 / Looking back in 2026'],'title':['如果今天重做：先定指标，再定奖励。','If I did it today: decide the metrics, then the rewards.'],'text':[
 ['当年的稿子其实把“活跃”拆过一次：试用、体验、习惯、分享四个阶段，各写了判断标准。今天我会再往前走一步，把它收成三个能直接看的数：激活是第一次从路线入口完成骑行，频次是每周骑行次数，留存是 30 天内是否回来再骑。然后把当年的触点逐一归位：首页 banner、寻宝地图和路线讨论圈管激活；骑行后的金币、宝箱和店铺券管频次；骑行回忆和风景卡管留存。这样一看，频次几乎全压在宝箱数值上。','The 2021 deck had already broken “active” down once, into four stages (trial, first rides, habit, advocacy), each with a threshold. Today I would go one step further and reduce it to three numbers that can be read directly: activation (a first ride started from a route entry point), frequency (rides per week) and retention (riding again within 30 days). Each 2021 touchpoint then has a place: the home banner, treasure map and route discussions serve activation; post-ride coins, chests and shop coupons serve frequency; ride memories and scenery cards serve retention. Seen this way, frequency rested almost entirely on the treasure-chest numbers.'],
 ['我会保留两样：奖励跟着骑行结算，而不是另开一份任务清单；骑行回忆，把一次骑行沉淀成可以回看的内容。我会砍掉宝箱升级：金、银、铜三级宝箱靠金币升级来提高掉率，可当年没有算过金币产出、券的成本和掉率。没有经济模型支撑的数值，上线后既难调整，也难收回。','I would keep two things: rewards settled after the ride, rather than a separate task list; and ride memories, which turn a ride into something worth revisiting. I would cut the chest upgrades. Gold, silver and bronze chests were upgraded with coins to raise drop rates, but we never modelled coin issuance, coupon cost or drop rates. Numbers without an economic model are hard to tune once live, and harder to withdraw.'],
 ['我会先跑的实验只回答一个问题：奖励什么时候给。按用户随机分两组，A 组锁车后立即结算，B 组把奖励延后汇总再发放；主指标是 7 天复骑率，同时盯住每次复骑对应的奖励成本。“奖励要紧贴骑行”是当年方案默认的前提，但从来没有被检验过。','The first experiment I would run answers one question: when should the reward arrive? Users are randomised into two groups. Group A gets the reward the moment the bike is locked; group B gets it batched and delivered later. The primary metric is the 7-day repeat-ride rate, with reward cost per repeat ride as a guardrail. “Rewards should sit right next to the ride” was an assumption of the 2021 proposal, and it was never tested.'],
 ['回头看，当年最缺的是一次用户测试：低保真流程只在团队内部测过，没有请骑行者试用。','Looking back, what the project lacked most was a test with users: the wireframe flow was only tested within the team and never tried by riders.']],
 'insight':['先写下要看哪个数，奖励设计才有东西可以对照。','Name the number you will watch before designing the reward; otherwise there is nothing to judge it against.']}
 ]},
'playbook': {
 'title':['PlayBook：把复杂规则，变成可参与的体验。','PlayBook: complex rules, meaningful participation.'],
 'deck':['创作者在 Studio 中定义活动与物品规则，粉丝在 App 中参与、收集与合成。我连接两端的交互逻辑，让自由度变得可以理解。','Creators define campaigns and item rules in Studio; fans participate, collect and craft in the App. I connected the interaction logic between these two sides.'],
 'brief':[['创作者可以在 Studio 里自由配置合成规则。自由度越高，创作者和粉丝越难看懂这条规则怎么运作。', 'Creators can configure crafting rules freely in Studio. The more freedom they have, the harder it is for creators and fans to see how a rule actually works.'], ['把规则做成画布上能摆弄的积木，而不是一张表单；粉丝端放弃游戏化的“熔炉”，改成先看清要付出什么、再确认合成；搜索从“只在一位创作者内”改成全局入口。', 'I made the rule a set of blocks you can handle on a canvas rather than a form; dropped a game-like “furnace” on the fan side so that people see the cost before they confirm; and moved search from a single creator’s community to a global entry.'], ['演示原型被客户方创始人用在面向投资人的路演里，项目获得投资。', 'The client’s founder used the interactive prototypes in investor pitches, and the project secured investment.']],
 'facts':[['项目背景','Context','创业团队 · 海外创作者平台','Startup · Creator & fan platform'],['我的职责','My role','Studio UX/UI · App UX','Studio UX/UI · App UX'],['项目时间','Period','2023–2024','2023–2024'],['交付','Delivery','交互流程、界面、状态与演示原型','Flows, interfaces, states & prototypes']],
 'image':'studio-campaign','source':'https://www.figma.com/design/XDyOn5545LrSOsCwqUcED7?node-id=5562-28622',
 'sections':[
 {'label':['01 / 产品关系','01 / Product model'],'title':['一条规则，连接创作者与粉丝。','One rule connects the creator and the fan.'],'text':[
 ['PlayBook 希望让创作者与粉丝的关系在不同内容平台之间保持连续。产品探索通过任务、可收集物品和合成规则，让粉丝表达参与与支持。它需要作为原有内容渠道的补充，帮助用户回到创作者的内容。','PlayBook aimed to keep the relationship between creators and fans continuous across content platforms. Tasks, collectible items and crafting rules offered ways for fans to express participation. The product needed to complement existing channels and lead people back to the creator’s content.'],
 ['我负责 Studio 的 UX 与 UI，以及 App 的 UX 流程和交互状态；App 的视觉 UI 由另一位设计师完成。两端的核心挑战相同：一项自由配置的规则，到了使用时必须能被理解。','I designed Studio’s UX and UI, alongside the App’s UX flows and interaction states. Another designer created the App’s visual UI. Both sides shared a core challenge: a freely configured rule must become understandable when someone uses it.']],
 'steps':[
 [['Studio','Studio'],['配置','Configure'],['创作者组织活动、任务、物品与合成规则。','Creators organise campaigns, tasks, items and crafting rules.']],
 [['App','App'],['参与','Participate'],['粉丝在创作者社区中找到任务并获得物品。','Fans find tasks in a creator’s community and acquire items.']],
 [['Community','Community'],['表达联系','Express connection'],['通过收集、使用与展示物品，体现与创作者的关系。','Collecting, using and displaying items reflects the relationship with the creator.']]]},
 {'label':['02 / 用户与动线','02 / Users & flow'],'title':['粉丝打开 App，先想知道自己又得到了什么。','Fans open the app to see what they have just earned.'],'text':[
 ['客户方的需求文档列出了粉丝打开 PlayBook 的九个理由。排在第一位的是：在社交平台上和创作者互动之后，回来看看自己拿到了多少奖励。其余理由大致分三类：看动态、管收藏、和创作者及其他粉丝互动。','The client’s requirements listed nine reasons a fan would open PlayBook. The first was to check what they had earned after engaging with a creator on social media. The rest fell into three groups: following activity, managing a collection, and interacting with creators and other fans.'],
 ['我按两端三类人来理解用户。粉丝一侧，我和一些看虚拟主播的观众聊过，了解他们为什么看、对哪些信息着迷，再结合自己作为直播观众的经验，整理出老粉和新粉两类画像。创作者一侧的信息来自客户方与创作者及其公司的沟通。','I worked from three user types across the two sides of the product. On the fan side, I talked with viewers of virtual streamers about why they watch and what draws them in, combined that with my own experience as a livestream viewer, and wrote two personas: the long-time supporter and the newcomer. What I knew about creators came from the client’s conversations with creators and their agencies.'],
 ['需求文档把 App 画成五个平行视图：主页面、任务、物品制作、库存、社区。我按粉丝一次回访的顺序，把它们串成一条链路：在首页看到奖励和进行中的任务，去完成任务（有的要回到原平台），领取物品，在图鉴里看还缺什么，再合成、交易或交换，最后展示出来。','The requirements described the app as five parallel views: Home, Missions, Crafting, Inventory and Community. I arranged them in the order a fan moves through on one visit: see rewards and open missions on Home, complete missions (some on the original platform), claim items, check what is missing in the catalogue, craft, trade or swap, and finally show items off.']],
 'steps':[
 [['粉丝 · 老粉','Fan · long-time supporter'],['跨平台追随的老粉','Follows a creator across platforms'],['看直播、关注社交账号、买周边。主播换主平台时，过往的粉丝牌和等级跟着消失；长期的支持也很少被主播看见。需要贡献被记下来，并且能展示出来。','Watches streams, follows the creator’s social accounts and buys merchandise. When the creator moves to a new main platform, past badges and levels disappear, and long-term support often goes unnoticed. Needs contributions to be kept and visible.']],
 [['粉丝 · 新粉','Fan · newcomer'],['刚入坑的收集者','A new fan who likes collecting'],['刚开始追一位主播，被稀有物品和活动吸引。除了点赞和评论，没有更深的参与方式，也还不知道哪些物品珍贵。需要知道今天能做什么、还缺什么、去哪里拿。','Has just started following a creator and is drawn to rare items and events. Beyond likes and comments there is little to do, and they don’t yet know which items are valuable. Needs to know what to do today, what is missing and where to get it.']],
 [['创作者 · Studio 端','Creator · Studio'],['有人设和故事的虚拟主播','A VTuber with a character and a story'],['在 YouTube、Twitch 等平台之间经营粉丝，换主阵地时粉丝会大量流失，也看不清谁是长期支持者。需要把任务、物品、配方和活动配置成粉丝看得懂的规则。','Builds an audience across YouTube, Twitch and other platforms, loses many fans when switching main platform, and can’t easily see who the long-term supporters are. Needs to turn missions, items, recipes and campaigns into rules fans can understand.']]],
 'insight':['新粉还不知道哪些物品珍贵。这个冷启动问题，让展示柜从“自己布置”改成了“系统推荐、一键展示”。','New fans don’t yet know which items are valuable. That cold-start problem turned the showcase from self-curated into recommended, one-tap display.']},
 {'label':['03 / Studio','03 / Studio'],'title':['编辑规则时，就能看见它如何运作。','Show the logic while the rule is being edited.'],'text':[
 ['规则编辑器把必需输入、可选输入、条件分支与输出放在同一张画布上。以原稿中的配方为例，手柄与电池是必需材料，增压器是可选材料；是否选择它，决定输出属性如何计算。','The rule editor places required inputs, optional inputs, conditional branches and outputs on one canvas. In the source example, a gamepad and battery are required, while a supercharger is optional. Selecting it changes how an output attribute is calculated.'],
 ['这种结构让创作者能追踪输入与结果的关系。代价是画布复杂度：自由度越高，越需要验证首次使用者能否找到入口、解释自己建立的规则，以及修正错误。','This structure makes the relationship between inputs and outcomes traceable. Its trade-off is canvas complexity: greater flexibility makes it more important to test whether first-time creators can find the entry point, explain their rule and correct mistakes.']],
 'image':'studio-editor','caption':['Studio 配方编辑器原稿，个人负责 UX/UI。','Original Studio recipe editor; my UX/UI work.']},
 {'label':['04 / App','04 / App'],'title':['让粉丝先理解代价，再确认合成。','Make the cost clear before the fan confirms.'],'text':[
 ['手机端的改版从 2023 年 10 月下旬开始，做了三到四周。合成是改动最大的一处：从游戏化的“熔炉”，改成配方浏览加消耗确认。','The app redesign started in late October 2023 and took three to four weeks. Crafting changed the most: from a game-like “furnace” to recipe browsing with a consumption check.'],
 ['材料不足、条件满足和确认合成是三个不同状态。即使提供快速合成，也需要让用户在承诺之前看清楚会失去什么、得到什么。','Missing materials, requirements met and confirmation are distinct states. Even quick crafting needs to make the consequence clear before the user commits.']],
 'decision':[
 ['合成会消耗物品，而且不能撤销。不同创作者的配方可能用同样的材料、产出不同的物品，粉丝得先看懂用的是哪条配方、会失去什么。','Crafting consumes items and cannot be undone. Recipes from different creators can share inputs but produce different outputs, so fans need to see which recipe applies and what they will give up.'],
 ['我最早画的是游戏化的“熔炉”：把材料拖进屏幕中央的熔炉，配方自动填好，一点就合成，保留一点惊喜感。','My first design was a game-like “furnace”: drag materials into a cauldron in the centre of the screen, the recipe fills itself in, and one tap crafts, with an element of surprise.'],
 ['客户方产品负责人认为太复杂。PlayBook 是辅助型 App，领取和合成越简单越好，目标是让粉丝回到创作者原来的平台。配方之间还会重叠，材料拖进熔炉以后，说不清用的是哪一条。','The client’s product lead found it too complex. PlayBook is a companion app: claiming and crafting should be as simple as possible, because the goal is to send fans back to the creator’s own platforms. Recipes can also overlap, and a furnace cannot show which one is being used.'],
 ['合成收进一个专属页面，物品页改成图鉴，只留快速合成入口。长按配方卡片会弹出确认框，写明会失去哪些物品、会得到哪些物品。新用户点进配方详情再合成，熟练用户走长按的快捷路径。以物换物沿用同一条确认规则。','Crafting moved to one dedicated page, and item pages became a catalogue with a quick-craft entry. Long-pressing a recipe card opens a confirmation that lists the items you will lose and the items you will get. Newer users go through the recipe detail; experienced users take the long-press shortcut. Barter uses the same confirmation.']],
 'phones':['app-craft-insufficient','app-craft-ready','app-craft-confirm'],
 'caption':['App 原始 UX 状态：材料不足 → 满足要求 → 确认合成。App 视觉 UI 为另一位设计师的贡献。','Original App UX states: missing materials → requirements met → confirm crafting. App visual UI was another designer’s contribution.']},
 {'label':['05 / 上下文与发现','05 / Context & discovery'],'title':['社区上下文保持一致，发现入口允许跨越。','Keep community context coherent, but discovery open.'],'text':[
 ['首页、物品与任务都需要回答“这是哪位创作者的社区”。我把创作者切换视为共享上下文，让相关内容保持一致。','Home, items and missions need to answer the same question: whose community is this? I treated creator selection as shared context so related content remained coherent.'],
 ['我最初倾向于把搜索限制在单个创作者内。2023 年 10 月的产品评审明确了创作者联动的重要性，我们随后转向独立的全局搜索入口，覆盖创作者、物品、配方与用户。日常任务保留上下文，发现则可以跨社区。','I initially favoured search within a single creator’s world. In the October 2023 product reviews, creator collaboration emerged as a central goal. We moved toward a dedicated global search covering creators, items, recipes and users, retaining local context for everyday tasks.']],
 'insight':['一致的上下文帮助用户定位；过于严格的边界，也可能阻碍产品需要的连接。','Consistent context helps people orient themselves. A boundary that is too strict can prevent the connections the product needs.']},
 {'label':['06 / 反馈与协作','06 / Feedback & collaboration'],'title':['小进度，不需要每次都打断用户。','Small progress should not always interrupt.'],'text':[
 ['在评审中，我提出日常小任务与重大成就不应使用同等强度的反馈。频繁全屏弹窗会打断内容体验；较轻的反馈可以承接日常进展，重要奖励则保留明确的领取动作。','In reviews, I argued that routine tasks and significant achievements should not receive equally intrusive feedback. Frequent full-screen dialogs interrupt the experience. Lighter feedback can support everyday progress, while valuable rewards keep an intentional claim step.'],
 ['这些取舍通过页面、状态与交互演示进入产品讨论，也被用于团队对外的产品与投资沟通。设计的作用，是把抽象规则变成团队可以共同检视的行为。','Screens, states and interaction demonstrations brought these trade-offs into product discussions and supported product and investor communication. The design made abstract rules concrete enough for the team to examine together.']],
 'decision':[
 ['原稿里“任务完成”和“奖励到手”是同一个状态。粉丝回到 App，分不清哪些做完了、哪些还等着领取；首页任务一多，就看不出重点。','In the original UI, “task done” and “reward received” were one state. Returning fans couldn’t tell what was finished and what was still waiting to be claimed, and a long task list on Home buried what mattered.'],
 ['全自动：登录时系统判定任务完成，直接发放奖励，不用点。评审里我对每日任务提过这个做法。','Fully automatic: on login, the system marks tasks complete and issues rewards with no tap. I suggested this for daily tasks during a review.'],
 ['客户方产品负责人希望奖励由粉丝亲手点一下来收。我也认为，珍贵的长期任务要自己接受、自己领取才有成就感；简单任务的进度变化又太频繁，每次都弹窗只会打扰。','The client’s product lead wanted fans to tap to collect their rewards. I also argued that rare, long-term tasks only feel earned when fans accept and claim them themselves, while progress on easy tasks changes so often that a dialog every time would only get in the way.'],
 ['“完成未领取”和“已领取”分成两个状态。每日任务自动判定完成，可以逐个领取，也可以一键全部领取；高价值任务保留手动领取和奖励弹窗。首页只放 3 到 5 个进行中或待领取的任务，领过的离开首页。大进展用全屏弹窗，小进展只在右上角显示 +N。','Two separate states: completed-but-unclaimed and claimed. Daily tasks are detected automatically and can be claimed one by one or all at once; high-value tasks keep a manual claim and a reward dialog. Home shows only three to five tasks that are in progress or waiting to be claimed, and claimed tasks leave Home. Major progress gets a full-screen dialog; minor progress shows a small “+N” in the top corner.']]},
 {'label':['07 / 收藏与展示','07 / Collection & showcase'],'title':['库存负责管理，展示柜负责表达。','Inventory manages. The showcase expresses.'],'text':[
 ['原来的物品页同时承担管理、合成、展示三件事。我把它们拆开：库存只回答三个问题，我有什么、还缺什么、怎么获得；合成去专属页面；展示交给展示柜。','The original item page tried to manage, craft and display at the same time. I separated them: Inventory answers three questions (what I have, what I’m missing, and how to get it), crafting has its own page, and display belongs to the showcase.']],
 'decision':[
 ['首页和个人主页都留了展示物品的位置，但原稿没有说明在哪里设置、没有物品时显示什么。','Home and the profile both had space for displayed items, but the original UI never said where those items were chosen or what appeared when there were none.'],
 ['参考索尼的奖杯展示柜：由粉丝自己挑选、自己布置收藏。','A self-curated trophy cabinet in the style of Sony’s, where fans pick and arrange their own collection.'],
 ['客户方产品负责人提出了冷启动问题：新粉还不知道哪些物品珍贵，不会主动去布置。','The client’s product lead raised the cold-start problem: new fans don’t yet know which items are valuable, so they won’t set up a cabinet on their own.'],
 ['展示柜从粉丝的背包里推荐珍贵物品，一键展示，让人发现“原来我还有这个”。展示柜补齐了四个状态：未填充、推荐选择、已填充、访客视角。','The showcase recommends valuable items from the fan’s inventory and displays them in one tap (“I didn’t know I had this”). It covers four states: empty, choosing from recommendations, filled, and the visitor’s view.']]},
 {'label':['08 / 交易与交换','08 / Trading & barter'],'title':['买、卖和交换，都先说清代价。','Buying, selling and swapping all state the cost first.'],'text':[
 ['缺的物品除了做任务和合成，还可以在社区里买，或者拿自己多余的物品去换。我为交易市场和以物换物画了约 27 屏线框：市场与库存、挂单与求购、价格走势、上架与购买确认，以及发起、接受和拒绝一次交换。','Besides missions and crafting, fans can buy a missing item in the community or swap spare items for it. I drew about 27 wireframes for the marketplace and barter: market and inventory, listings and buy requests, price trend, listing and purchase confirmation, and posting, accepting or refusing a swap.'],
 ['和客户方讨论之后，我把自己还没想清楚的问题记在了线框旁边：“以物换物的出发点是什么”“steam 的以物换物：首先是 1 对 1，为什么不做 1 对多呢”“订单查看、交易和以物换物的订单是否需要一个单独的模块进行查看，或是集成在消息里？”问题下面，我列出了三个页面：以物换物市场、我的以物换物请求、我想要的物品。','After discussions with the client, I wrote the questions I had not yet resolved next to the wireframes (translated from my Chinese notes): “What is barter for in the first place?” “Steam’s trading is one-to-one. Why not one-to-many?” “Do trade and barter orders need a module of their own, or should they live inside messages?” Below the questions I listed three pages: the barter market, my barter requests, and the items I want.'],
 ['两条流程都在最后一步写明代价。购买前列出数量、单价和应付总额；交换时把会失去的物品和会得到的物品分成上下两栏，确认之后才发出。这和合成用的是同一条规则。','Both flows spell out the cost at the last step. A purchase lists quantity, price and total due before it goes through; a swap separates the items you will lose from the items you will gain, and is only sent after confirmation. This is the same rule crafting follows.'],
 ['交易市场和以物换物这部分经过了评审，保留在方案里。','The marketplace and barter flows were reviewed and kept in the design.']]},
 {'label':['09 / 交付与反思','09 / Outcome & reflection'],'title':['团队可以讨论行为，而不只是页面。','The team could discuss behaviour, not just screens.'],'text':[
 ['交付覆盖 Studio UX/UI、App UX 流程与状态，以及演示原型，方案已交付开发。','The delivery included Studio UX/UI, App UX flows and states, and demonstration prototypes, and the design was handed over to development.'],
 ['演示原型被客户方创始人用在面向投资人的路演里，项目已获得投资。','The client’s founder used the interactive prototypes in investor pitches, and the project secured investment.'],
 ['如果重做，我会把 Studio 和 App 两端的对照打磨得更细。当时大部分精力花在原型上，第一版手机端给得很快，客户方也想尽快拿出能给投资人看的版本，很多信息我没有问全。我和开发之间的沟通也都经过创始人转述。','If I did it again, I would refine how the two sides, Studio and App, map to each other. Most of my effort went into prototypes. The first app version came quickly, the client wanted something to show investors as soon as possible, and I did not ask for all the information I needed. Communication with the developers also went through the founder.'],
 ['我学到的是：先把主要人群的主流程做扎实，再处理极端情况。当时我们在名称过长这类边界情况上花了很多时间，大多数粉丝会走的路径反而想得不够。我也不再把线框当成“理顺思路就交给 UI”的中间稿：线框做得粗，问题会留到后面。','What I learned: get the main flow right for the main group of users before handling edge cases. We spent a lot of time on cases such as overly long names, and less on the path most fans would take. I also stopped treating wireframes as a rough pass that the UI stage would fix. Rough wireframes leave problems for later.']], 'outcome':True}
 ]},
'smt': {
 'title':['兴业 SMT：从业务单元，建立界面秩序。','Industrial Securities SMT: a shared structure for financial workflows.'],
 'deck':['在武汉优品楚鼎科技有限公司任职期间，我与同事共同研究业务模块的拆分，负责相关 Figma 组件、使用规范与维护，让高密度金融界面能够复用。','At Wuhan Youpin Chuding Technology, I worked with colleagues to break down business modules, then designed and maintained the relevant Figma components and specifications.'],
 'brief':[['证券软件里，长得一样的控件可能对应完全不同的业务后果。只按外观做组件，会复用错。', 'In securities software, controls that look the same can carry very different business consequences. Components split by appearance alone get reused in the wrong places.'], ['按业务含义而不是外观划分组件边界；给持仓表格定下默认、选中、悬停、无数据四种状态，状态变了，信息的位置和阅读顺序不变。', 'I set component boundaries by business meaning rather than appearance, and defined four states for the positions table — default, selected, hover and no data — so that feedback changes while position and reading order stay put.'], ['参与兴业证券 SMT 5.0 交易系统改造，已开发上线；这套组件用于跨项目复用和日夜两套主题。', 'Part of the redesign of Industrial Securities’ SMT 5.0 trading system, which was built and launched; the components were reused across projects and in day and night themes.']],
 'facts':[['项目背景','Context','武汉优品楚鼎科技有限公司 · 兴业 SMT','Wuhan Youpin Chuding Technology · Industrial Securities SMT'],['我的职责','My role','组件设计、使用规范与维护','Component design, specifications & maintenance'],['协作方式','Collaboration','与同事共同研究业务单元拆分','Collaborative business-unit decomposition'],['交付范围','Delivery','Figma 组件与规范','Figma components & guidelines']],
 'image':'smt-overview','source':'https://www.figma.com/design/RXWxFWgHwWEXBBcLQ6LlZB?node-id=0-5802',
 'sections':[
 {'label':['01 / 问题','01 / The challenge'],'title':['一张表格承载的，是一项业务任务。','A table carries a task, not just data.'],'text':[
 ['证券工具把账户、市场、持仓、数值和操作放在同一个密集工作面中。视觉相似的控件，可能对应完全不同的业务后果；因此，组件划分不能只看外观。','A securities tool brings accounts, markets, positions, values and actions into a dense working surface. Visually similar controls can have very different consequences, so component boundaries cannot be based on appearance alone.'],
 ['这次工作的目标，是在减少重复界面构建的同时，保留业务含义。我与同事共同研究组件库方法与业务单元拆分，再把相关结构推进到组件和规范。','The aim was to reduce repeated interface construction while preserving business meaning. I researched component-library methods and business-unit decomposition with colleagues, then developed the relevant structures into components and guidelines.']],
 'steps':[
 [['Context','Context'],['我在看哪个账户？','Which account?'],['账户和市场决定了如何理解数据。','Account and market context determine how the data should be understood.']],
 [['State','State'],['现在是什么状态？','What is happening?'],['默认、选中、悬停与无数据需要不同反馈。','Default, selected, hover and no-data states need distinct feedback.']],
 [['Action','Action'],['我可以执行什么？','What can I do?'],['操作应属于明确任务，并保留其业务意义。','Each action belongs to a task and must retain its business meaning.']]]},
 {'label':['02 / 拆分','02 / Decomposition'],'title':['用业务含义，而非视觉相似度，决定复用边界。','Use business meaning to decide what can be shared.'],'text':[
 ['以账户持仓为例，表格、账户上下文与操作控件可以拆分为可复用单元，同时保留它们之间的关系。共享结构只有在含义与行为相符时才成立。','For account positions, the table, account context and controls can become reusable units while keeping their relationships explicit. A shared structure only works when its meaning and behaviour match.'],
 ['我的职责包括相关组件设计、使用规范与持续维护。对于不同任务中特有的规则，保留差异比强行统一更重要。','My responsibility included the relevant component design, usage specifications and ongoing maintenance. Where tasks have different rules, preserving those differences matters more than forcing consistency.']],
 'insight':['组件的边界，也是一项产品设计决策。','A component boundary is also a product-design decision.']},
 {'label':['03 / 状态','03 / States'],'title':['状态变化，阅读结构保持稳定。','Let state change without moving the reading structure.'],'text':[
 ['源文件的“表格／账户持仓”组件包含默认、选中、悬停与无数据变体。反馈需要让用户理解发生了什么，同时保持信息的位置与阅读顺序稳定。','The source “Table / Account Positions” component includes default, selected, hover and no-data variants. Feedback needs to explain what changed while keeping information position and reading order stable.'],
 ['这使组件规范不仅回答“长什么样”，还明确“在不同情况下如何表达”。一致的状态定义，也为后续维护提供共同依据。','The specification therefore addresses both appearance and behaviour across situations. Consistent state definitions also give maintenance work a shared reference.']],
 'image':'smt-states','caption':['账户持仓组件的原始状态截取。源组件还包含无数据变体。','Original account-position state crop. The source also includes a no-data variant.']},
 {'label':['04 / 规范与维护','04 / Specifications & maintenance'],'title':['复用结构，保留操作的不同含义。','Share the structure; preserve the meaning of the action.'],'text':[
 ['买入、卖出、确认、取消和输入控件具有相关结构，但它们不是同一种动作。我维护这些组件与规范，让重复模块有一致基础，同时保留任务之间的区别。','Buy, sell, confirm, cancel and input controls have related structures, but are not the same action. I maintained components and specifications to give repeated modules a consistent foundation while preserving these distinctions.'],
 ['组件被用于跨项目复用与日夜主题适配。','The components supported cross-project reuse and day/night theme adaptation.']],
 'image':'smt-trade-components','caption':['原始控件与变体：我负责设计与维护的组件。','Original controls and variants: the components I designed and maintained.']},
 {'label':['05 / 界面','05 / Screens'],'title':['从组件到整页。','From components to full screens.'],'text':[
 ['除了组件，我还画了这套系统里的整页界面：资产首页、快速挂单、篮子下单和网格策略。每一页都由同一批组件拼成：账户选择栏、下单板、盘口和持仓表，在不同页面里长得一样、位置也一样。','Beyond the components, I designed full screens for the system: the asset home, quick order, basket order and grid strategy. Each screen is assembled from the same set of components — the account selector, order panel, order book and positions table look the same and sit in the same place from one screen to the next.']]},
 {'label':['06 / 适老化方案','06 / Age-friendly design'],'title':['把「适老化」拆成能照着做的规则。','Turning “age-friendly” into rules a team can build from.'],'text':[
 ['2022 年 4 月到 6 月，我为大通证券的交易 App 做了一套「关怀版」方案：把客户的适老化升级需求拆成交易流程里的交互规则，再一页一页落到界面上，做成完整的原型提案。','From April to June 2022 I designed a “Care mode” proposal for Daton Securities’ trading app: I broke the client’s age-friendly upgrade requirement down into interaction rules for the trading flow, applied them screen by screen, and delivered a complete prototype proposal.'],
 ['<b>字放大。</b>核心文字和操作按钮放大到 1.25 倍，页面上最小的字不小于 18pt。','<b>Larger type.</b> Core text and action buttons are scaled to 1.25×; no text on a screen is smaller than 18pt.'],
 ['<b>点得准。</b>首页主要组件的可点区域大于 60×60pt，其他页面大于 44×44pt。','<b>Bigger tap targets.</b> Tap areas of main components are larger than 60×60pt on the home screen and 44×44pt elsewhere.'],
 ['<b>图标换成文字。</b>首页的图标和简写改成文字全称，底部标签改成大字。','<b>Words instead of icons.</b> Icons and abbreviations on the home screen become full text labels; the bottom tabs become large text.'],
 ['<b>放大以后重排版面。</b>字和按钮变大后，版面改成单列，盘口移到下方；能合并的输入项合并，比如输入股票代码后由系统判断所属市场。','<b>Re-lay out after enlarging.</b> With larger type and buttons, screens move to a single column and the order book moves below the form. Inputs that can be merged are merged: enter a stock code and the system picks the market.'],
 ['<b>不用新奇的交互。</b>币种切换从滑动改成文字按钮加底部弹窗；点一只持仓的股票，也是从底部弹出操作。','<b>No novel interactions.</b> Currency switching changes from a swipe to a text button plus a bottom sheet; tapping a holding also opens a bottom sheet.'],
 ['<b>次要的往后放。</b>按信息类型、使用频率和重要性归类：常用功能放进大格子和高对比的色块，老年用户用得少的功能弱化。','<b>Secondary features step back.</b> Features are grouped by information type, frequency of use and importance: frequent ones get large tiles and high-contrast blocks, and those older users rarely need are toned down.'],
 ['方案被公司采纳为通用的适老化提案用于投标，后来申港证券的投标沿用了它；原型也拆成了团队可复用的组件。','The company adopted the proposal as its standard age-friendly pitch for bids, and it was reused in a later bid for Shengang Securities. The prototype was also broken down into components the team could reuse.']]},
 {'label':['07 / 交付与反思','07 / Outcome & reflection'],'title':['可复用的设计基础，来自明确的边界。','A reusable design foundation starts with clear boundaries.'],'text':[
 ['这些组件和规范用在兴业证券 SMT 5.0 交易系统的改造里，系统已开发上线。我交付 Figma 组件、使用规范与维护，并参与了方法研究和业务拆分。','The components and guidelines went into the redesign of Industrial Securities’ SMT 5.0 trading system, which was built and launched. I delivered the Figma components, usage guidelines and their maintenance, and contributed to the shared method research and business decomposition.'],
 ['如果继续验证这套方法，我会比较重复模块的组装时间、遗漏状态的数量，以及一次修改同步到多个实例的维护成本。它们能更具体地判断复用是否真正帮助了团队。','To evaluate this approach further, I would compare repeated-module assembly time, omitted states and the effort needed to carry a change across instances. These measures would show more concretely whether reuse helps the team.']], 'outcome':True}
 ]},
'commons-fridge': {
 'title':['The Commons Fridge：共享空间，也共享清晰的边界。','The Commons Fridge: shared space, clearer boundaries.'],
 'deck':['通过五次习惯访谈，把全量库存管理的设想转向更轻量的共享协调：看见物品，了解归属，再决定可以做什么。','Five habit interviews redirected a full-inventory concept toward lighter shared coordination: see the item, understand ownership, then decide what can be done.'],
 'brief':[['合租共用一台冰箱，麻烦不只是忘了东西，还有不好意思提醒别人、总是同一个人在整理、谁的东西谁能动说不清。', 'In a shared flat, the trouble with one fridge is not only forgotten food: people hesitate to remind each other, the same person ends up tidying, and nobody is sure whose things can be touched.'], ['放弃“所有东西都登记”的方案，只在四个时刻帮忙：放进去、查看处理、买菜之前、发现东西。把“在哪、是谁的、别人能做什么”分成三件事，没人认领的东西保持“不确定是谁的”。', 'I dropped the full-inventory idea and designed for four moments only: putting something in, checking and handling, before shopping, and finding something. Where an item is, whose it is and what others may do are three separate things; an unclaimed item stays “not sure whose”.'], ['做出能运行的中英双语原型，和冰箱门上的 NFC 入口。', 'A working bilingual prototype, and NFC entry points on the fridge door.']],
 'facts':[['项目背景','Context','南安普顿大学 · 硕士毕业设计','University of Southampton · MA final project'],['我的职责','My role','研究、系统设计、交互与功能原型','Research, system design, interactions & prototype'],['项目时间','Period','2026','2026'],['交付','Delivery','实体入口、双语原型与研究者演示','Physical touchpoints, bilingual prototype & demonstration']],
 'image':'fridge-p1-0','source':'https://www.figma.com/design/lx9WbYRybWceTemdXVkoJj?node-id=190-148',
 'sections':[
 {'label':['01 / 研究','01 / Research'],'title':['冰箱里的问题，也是人与人之间的问题。','The friction is social as well as practical.'],'text':[
 ['我通过五次访谈了解人们已有的共享冰箱习惯。研究中出现的不只是“忘记了什么”，还有提醒别人时的顾虑、长期由一个人承担的整理工作，以及模糊边界下反复发生的冲突。','I conducted five interviews about existing shared-fridge habits. The problems went beyond forgotten items: hesitation about reminding someone, recurring care work falling to one person, and repeated conflict around unclear boundaries.'],
 ['例如，U02 担心群消息听起来像抱怨；U01 承担检查和整理；U05 的经历反映了边界与容量压力如何影响参与。','U02 worried that a group message could sound like a complaint; U01 carried the work of checking and organising; U05 described how boundaries and capacity pressure affected participation.']],
 'insight':['让下一步行动更清楚，同时避免把提醒变成“谁做错了”的公开记录。','Make the next shared action clearer without turning a reminder into a public record of who failed.']},
 {'label':['02 / 设计转向','02 / Reframing'],'title':['减少管理负担，而不是建立更大的台账。','Reduce the burden instead of building a bigger inventory.'],'text':[
 ['最初的全量记录方案依赖每个人不断输入与维护信息，可能给已经承担整理的人增加工作。我把重心转向几个真正需要协调的时刻：放入物品、检查处理、购物前查看，以及搬走时交接。','A complete inventory depends on people continually entering and maintaining information. That can add work for the person already doing the organising. I shifted toward moments that need coordination: putting something in, checking or handling it, shopping and moving out.']],
 'steps':[
 [['Put in','Put in'],['记录意图','Declare a plan'],['只记录与下一步有关的计划，而非要求完整登记。','Capture the chosen plan rather than demand a complete inventory.']],
 [['Check','Check'],['看见需要关注的事','See what needs attention'],['按区域组织信息，避免把人变成问题标签。','Group by area rather than attaching a problem label to a person.']],
 [['Coordinate','Coordinate'],['保留归属与权限','Respect ownership'],['看到一件物品，并不意味着获得处置它的权限。','Seeing an item does not give someone permission to dispose of it.']]]},
 {'label':['03 / 从研究到功能','03 / From findings to features'],'title':['每一个功能，都能倒推回一条被说出来的行为。','Every feature walks back to a behaviour someone described.'],'text':[
 ['把五场访谈编码成行为卡之后，我整理出九种共享冰箱会失灵的方式（FP1–FP9）。每一种都是跨访谈出现的模式，不是单个故事，并且标明出自哪几场访谈，方便回头核对。','After coding the five interviews into behaviour cards, I identified nine ways a shared fridge fails (FP1–FP9). Each is a pattern seen across interviews rather than a single anecdote, and each names the interviews that produced it, so it can be checked.'],
 ['原型里的每一项功能都对着其中一个失效点。例如 FP2（同样的包装、没有主人、占位几个月）对应“发现东西”入口：归属锁定为未知，并保留 48 小时；FP9（有人为了避免冲突而退出）对应四步搬出交接。','Each feature in the build answers one of them. FP2 — identical packaging with no owner occupying space for months — became a found-something entry that locks ownership to unknown with a 48-hour hold. FP9 — a user withdrawing to avoid conflict — became a four-step move-out handover.']],
 'insight':['如果一个功能倒推不回去，我就把它标成设计判断，而不是研究发现。','If a feature cannot be walked back, I mark it as a design judgement rather than a finding.']},
 {'label':['04 / 交互规则','04 / Interaction rules'],'title':['位置、归属、权限，是三件不同的事。','Location, ownership and permission are separate.'],'text':[
 ['我将物品在哪里、谁声明拥有它，以及别人可以做什么分开。无人认领的物品保持“未知归属”；位置和照片都不能自动证明所有者，也不能自动授权他人处理。','I separated where an item is, who claims it and what someone else may do with it. Unclaimed items retain unknown ownership. Neither a location nor a photograph automatically establishes an owner or permission to act.'],
 ['House 视图按区域分组，而不是按人分组。角色只描述情境，不评价个人；界面也不判断食物是否安全，判断与行动仍由人做出。','The House view groups items by area, not by person. The character describes situations without judging people. The interface does not determine food safety; judgement and action remain with the person.']],
 'image':'fridge-p22-0','caption':['提交稿中的功能界面截图：设计规则与可运行流程。','Functional interface image from the submitted project: the rules and the working flow.']},
 {'label':['05 / 实体与数字','05 / Physical & digital'],'title':['把入口放在行动发生的地方。','Put the entry where the action happens.'],'text':[
 ['冰箱门上的 Add 与 Manage 是两个清晰的入口，分别支持放入时记录意图和查看已有物品。NFC 链接与二维码把实体提示连接到手机上的详细流程。','Add and Manage are two clear entry points on the fridge door: record an intention when putting something away, or review what is already there. NFC links and a QR fallback connect the physical prompt to the detailed phone flow.'],
 ['企鹅形象承担温和提醒的角色。我通过 AI 辅助视觉迭代，选择并整理了一套一致的角色系统，让提醒保持中性。','The penguin gives reminders a caring tone. I used AI-assisted visual iteration, then selected and refined a consistent character system.'],
 ['角色是用生成式图像工具一轮一轮改出来的。我先写下书面规格，再出图；每一轮改的是提示词本身，而不是把同一句重抽一遍。前两轮被直接否掉，其中一条理由是“像通用的 AI 吉祥物”；第四轮的扁平版进入了表情系统和印刷件。规格写在图之前，否掉一张图才有依据，而不是凭口味。','The character was iterated with a generative image tool. The written specification came before the images, and each round rewrote the prompt rather than re-rolling the same one. The first two rounds were refused outright — one reason on record is that they read as generic AI mascot art — and the flat fourth round was carried into the expression system and the printed pieces. Because the specification came first, refusing a render was a documented decision rather than a matter of taste.']],
 'image':'fridge-p18-1','caption':['真实厨房中的研究者演示：实体触点打开手机原型。','Researcher demonstration in a real kitchen: the physical touchpoint opens the phone prototype.']},
 {'label':['06 / 原型与结果','06 / Prototype & outcome'],'title':['从碰一下冰箱门，到确认一个计划。','From a tap on the fridge door to a confirmed plan.'],'text':[
 ['提交时的功能原型 v1.7 将七条路由与中英双语放在同一页面中；下面嵌入的是展览期更新的 v1.8。研究者演示记录了触碰入口、持物操作、输入信息与确认计划的路径。','The submitted v1.7 functional prototype brings seven routes and both languages into one page; the one embedded below is v1.8, updated for the exhibition. A researcher demonstration documents the sequence of touching the entry, working with an item, entering details and confirming a plan.'],
 ['下一步是请参与者实际使用这条路径，测试材料已经备好，见下一节。','The next step is to put this journey in front of participants; the test materials are ready — see the next section.']],
 'external':['https://ideaism.github.io/commons-fridge-functional-v1/',['打开功能原型 ↗','Open the functional prototype ↗']], 'outcome':True},
 {'label':['07 / 下一步','07 / Next iteration'],'title':['先观察人如何使用，再判断设计是否成立。','Observe use before claiming effectiveness.'],'text':[
 ['下一轮会优先验证“计划”式表达能否被首次使用者理解，再比较角色方向与 NFC 入口。比较测试的材料已经备好，测试会在合适的研究范围与同意流程下开展。','The next iteration would test whether first-time users understand the plan-based framing, then compare character directions and NFC entry points. The comparison kit is ready; testing will run under an appropriate research scope and consent process.'],
 ['我也希望寻找能够成功维护共享库存的反例家庭。现有样本对失败的描述更充分，反例能帮助判断哪些复杂度应该保留、哪些可以删去。','I would also seek a household that successfully maintains a shared inventory. The existing sample describes failure more fully; a counterexample could clarify which complexity is useful and which can be removed.']]}
 ]}
}
